const API_BASE = `${process.env.REACT_APP_API_URL || `http://${window.location.hostname === 'localhost' ? 'localhost' : window.location.hostname}:5000`}/api/auth`;

export const updateProfile = async (payload) => {
  const token = localStorage.getItem('okoa_access_token');
  const response = await fetch(`${API_BASE}/me`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
    body: JSON.stringify(payload),
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(data.error?.message || data.error || 'Unable to update profile.');
  return data.user;
};
